"use client";

import React, { useRef } from "react";
import ServicesCard from "@/app/components/ServicesCard";
import img1 from "@/assets/s1.png";
import img2 from "@/assets/s2.png";
import img3 from "@/assets/s3.png";
import img4 from "@/assets/s4.png";
import { StaticImageData } from "next/image";

interface Service {
  title: string;
  img: StaticImageData;
}

const services: Service[] = [
  {
    title: "Installation",
    img: img1,
  },
  {
    title: "Maintenance",
    img: img2,
  },
  {
    title: "Repair",
    img: img3,
  },
  {
    title: "Consultation",
    img: img4,
  },
  {
    title: "AMC",
    img: img4,
  },
];

const Services: React.FC = () => {
  const scrollRef = useRef<HTMLDivElement>(null);
  let isDragging = false;
  let startX: number;
  let scrollLeft: number;

  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    isDragging = true;
    startX = e.pageX - (scrollRef.current?.offsetLeft || 0);
    scrollLeft = scrollRef.current?.scrollLeft || 0;
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!isDragging || !scrollRef.current) return;
    const x = e.pageX - (scrollRef.current.offsetLeft || 0);
    const walk = x - startX;
    scrollRef.current.scrollLeft = scrollLeft - walk;
  };

  const handleMouseUp = () => {
    isDragging = false;
  };

  const handleScrollLeft = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollBy({ left: -300, behavior: "smooth" });
    }
  };

  const handleScrollRight = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollBy({ left: 300, behavior: "smooth" });
    }
  };

  return (
    <section className="my-20 text-center relative">
      {/* Heading */}
      <h1 className="py-8 text-5xl font-bold animate-slideIn">Our Services</h1>

      {/* Buttons */}
      <div className="absolute left-4 top-2/3 transform -translate-y-1/2 z-10">
        <button
          onClick={handleScrollLeft}
          className="bg-gray-200 rounded-full p-2 shadow hover:bg-gray-300"
          aria-label="Scroll Left"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            fill="none"
            viewBox="0 0 24 24"
            strokeWidth={1.5}
            stroke="currentColor"
            className="w-6 h-6"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="M15.75 19.5 8.25 12l7.5-7.5"
            />
          </svg>
        </button>
      </div>
      <div className="absolute right-4 top-2/3 transform -translate-y-1/2 z-10">
        <button
          onClick={handleScrollRight}
          className="bg-gray-200 rounded-full p-2 shadow hover:bg-gray-300"
          aria-label="Scroll Right"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            fill="none"
            viewBox="0 0 24 24"
            strokeWidth={1.5}
            stroke="currentColor"
            className="w-6 h-6"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="m8.25 4.5 7.5 7.5-7.5 7.5"
            />
          </svg>
        </button>
      </div>

      {/* Horizontal Scrollable Cards */}
      <div
        ref={scrollRef}
        className="flex overflow-x-scroll gap-6 px-4"
        style={{ cursor: isDragging ? "grabbing" : "grab", scrollBehavior: "smooth" }}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >
        {services.map((service, index) => (
          <div key={index} className="flex-shrink-0 w-64">
            <ServicesCard title={service.title} img={service.img} />
          </div>
        ))}
      </div>
    </section>
  );
};

export default Services;
